// src/lib/redis.ts
import "dotenv/config";
var getRedisConfig2 = () => {
  if (process.env.UPSTASH_REDIS_REST_URL && process.env.UPSTASH_REDIS_REST_TOKEN) {
    return {
      url: process.env.UPSTASH_REDIS_REST_URL,
      token: process.env.UPSTASH_REDIS_REST_TOKEN
    };
  }
  console.warn("\u26A0\uFE0F  UPSTASH_REDIS_REST_URL is missing. Cache will not work.");
  return { url: "http://localhost:8079", token: "example_token" };
};
var redis2 = new Redis2(getRedisConfig2());
var cache2 = {
  async get(key) {
    try {
      const data = await redis2.get(key);
      return data;
    } catch (error) {
      console.error(`Cache GET error for key ${key}:`, error);
      return null;
    }
  },
  async set(key, value, ttlSeconds = 300) {
    try {
      await redis2.set(key, value, { ex: ttlSeconds });
    } catch (error) {
      console.error(`Cache SET error for key ${key}:`, error);
    }
  },
  async del(key) {
    try {
      await redis2.del(key);
    } catch (error) {
      console.error(`Cache DEL error for key ${key}:`, error);
    }
  },
  async delPattern(pattern) {
    try {
      const keys = await redis2.keys(pattern);
      if (keys.length > 0) {
        await redis2.del(...keys);
      }
    } catch (error) {
      console.error(`Cache DEL_PATTERN error for pattern ${pattern}:`, error);
    }
  }
};

