// src/lib/pdf/queue.ts
var JOB_TTL = 86400;
var pdfQueue = {
  async createJob(chapterId, filePath) {
    const jobId = `pdf-${chapterId}-${Date.now()}`;
    const job = {
      id: jobId,
      chapterId,
      filePath,
      status: "pending",
      createdAt: Date.now()
    };
    await redis.set(`job:${jobId}`, job, { ex: JOB_TTL });
    await redis.lpush("pdf-queue", jobId);
    return jobId;
  },
  async getJob(jobId) {
    return redis.get(`job:${jobId}`);
  },
  async updateJob(jobId, updates) {
    const job = await this.getJob(jobId);
    if (job) {
      await redis.set(
        `job:${jobId}`,
        { ...job, ...updates },
        { ex: JOB_TTL }
      );
    }
  },
  async dequeueJob() {
    return redis.rpop("pdf-queue");
  }
};

