pagesRoutes.post(
  "/chapters/:chapterId",
  authMiddleware,
  adminMiddleware,
  zValidator("json", addPageSchema),
  async (c) => {
    const chapterId = c.req.param("chapterId");
    const body = c.req.valid("json");
    const chapter = await db.query.chapters.findFirst({
      where: eq(chapters.id, chapterId)
    });
    if (!chapter) {
      return c.json({ success: false, error: "Chapter not found" }, 404);
    }
    const [page] = await db.insert(pages).values({ chapterId, ...body }).returning();
    await db.update(chapters).set({ pageCount: chapter.pageCount + 1 }).where(eq(chapters.id, chapterId));
    await cache.del(`pages:${chapterId}`);
    return c.json({ success: true, data: page }, 201);
  }
);
pagesRoutes.post(
  "/chapters/:chapterId/bulk",
  authMiddleware,
  adminMiddleware,
  zValidator("json", bulkAddPagesSchema),
  async (c) => {
    const chapterId = c.req.param("chapterId");
    const { pages: pageList } = c.req.valid("json");
    const chapter = await db.query.chapters.findFirst({
      where: eq(chapters.id, chapterId)
    });
    if (!chapter) {
      return c.json({ success: false, error: "Chapter not found" }, 404);
    }
    const inserted = await db.insert(pages).values(pageList.map((p) => ({ chapterId, ...p }))).returning();
    await db.update(chapters).set({ pageCount: chapter.pageCount + inserted.length }).where(eq(chapters.id, chapterId));
    await cache.del(`pages:${chapterId}`);
    return c.json(
      { success: true, data: inserted, count: inserted.length },
      201
    );
  }
);
pagesRoutes.delete("/:id", authMiddleware, adminMiddleware, async (c) => {
  const id = c.req.param("id");
  const page = await db.query.pages.findFirst({
    where: eq(pages.id, id)
  });
  if (!page) {
    return c.json({ success: false, error: "Page not found" }, 404);
  }
  await db.delete(pages).where(eq(pages.id, id));
  const chapter = await db.query.chapters.findFirst({
    where: eq(chapters.id, page.chapterId)
  });
  if (chapter) {
    await db.update(chapters).set({ pageCount: Math.max(0, chapter.pageCount - 1) }).where(eq(chapters.id, page.chapterId));
    await cache.del(`pages:${page.chapterId}`);
  }
  return c.json({ success: true, message: "Page deleted" });
});

