var trendingRoutes = new Hono2();
trendingRoutes.get("/", async (c) => {
  try {
    const period = c.req.query("period") || "7d";
    const limit = Math.min(
      Math.max(parseInt(c.req.query("limit")) || 20, 1),
      50
    );
    const offset = Math.max(
      parseInt(c.req.query("offset")) || 0,
      0
    );
    const result = await getTrendingManga(period, limit, offset);
    return c.json({
      success: true,
      data: result
    });
  } catch (error) {
    console.error("Trending endpoint error:", error);
    return c.json(
      {
        success: false,
        error: error instanceof Error ? error.message : "Failed to fetch trending manga"
      },
      400
    );
  }
});

