var app = new Hono2();
app.use("*", logger());
app.use("*", prettyJSON());
app.use(
  "*",
  cors({
    origin: [
      "http://localhost:4321",
      "http://localhost:3000",
      "https://mangaden.rejwanul.dev",
      "https://manga-den-frontend.vercel.app",
      "https://vm-manga-reader-frontend.vusercontent.net"
    ],
    credentials: true
  })
);
app.onError(errorHandler2);
app.get("/", (c) => {
  return c.json({
    success: true,
    message: "MangaDen API is running!",
    version: "1.0.0"
  });
});
app.get("/health", (c) => {
  return c.json({
    ok: true
  });
});
app.route("/api/manga", mangaRoutes);
app.route("/api/chapters", chapterRoutes);
app.route("/api/auth", authRoutes);
app.route("/api/upload", uploadRoutes);
app.route("/api/pages", pagesRoutes);
app.route("/api/user", userRoutes);
app.route("/api/trending", trendingRoutes);
app.route("/api/admin", adminRoutes);
app.notFound((c) => {
  return c.json(
    {
      success: false,
      error: "Not Found",
      message: `Route ${c.req.path} not found`
    },
    404
  );
});

